/**
 * Highlight + theme-color DOCX round-trip (change ooxml-roundtrip-fidelity).
 *
 * - Highlight: predefined names persist as `<w:highlight w:val="name"/>`;
 *   custom colors persist as `<w:shd w:val="clear" w:fill="RRGGBB"/>`
 *   (never the invalid `<w:highlight w:fill="..."/>` shape Word ignores).
 * - Theme color: `w:themeColor`/`w:themeTint`/`w:themeShade` survive
 *   load → save → reload alongside the resolved `w:val`, including
 *   theme-colored text in table headers.
 *
 * Fixtures are generated by `bun run e2e/fixtures/generate-fixtures.ts`
 * (generateHighlightRoundtripDocx / generateThemeColorRoundtripDocx).
 *
 * Word真机核验步骤见同目录 fixture 文档：
 * - e2e/fixtures/highlight-roundtrip-word-check.md
 * - e2e/fixtures/theme-color-roundtrip-word-check.md
 */

import { test, expect, type Page } from '@playwright/test';
import { EditorPage } from '../helpers/editor-page';
import * as assertions from '../helpers/assertions';
import * as fs from 'fs';
import * as path from 'path';
import { fileURLToPath } from 'url';
import JSZip from 'jszip';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const HIGHLIGHT_DOCX = path.join(__dirname, '..', 'fixtures', 'highlight-roundtrip.docx');
const THEME_DOCX = path.join(__dirname, '..', 'fixtures', 'theme-color-roundtrip.docx');

async function saveDownload(page: Page): Promise<string> {
  const downloadPromise = page.waitForEvent('download');
  await page.locator('text=Save').click();
  const download = await downloadPromise;
  const downloadPath = await download.path();
  expect(downloadPath).toBeTruthy();
  return downloadPath!;
}

test.describe('Highlight round-trip', () => {
  let editor: EditorPage;

  test.beforeEach(async ({ page }) => {
    editor = new EditorPage(page);
    await editor.goto();
    await editor.waitForReady();
  });

  test('named highlight and custom shd highlight survive save → reload', async ({ page }) => {
    await editor.loadDocxFile(HIGHLIGHT_DOCX);

    await assertions.assertDocumentContainsText(page, 'Named highlight yellow');
    await assertions.assertDocumentContainsText(page, 'Custom highlight pale yellow');

    const downloadPath = await saveDownload(page);
    const zip = await JSZip.loadAsync(fs.readFileSync(downloadPath));
    const docXml = await zip.file('word/document.xml')!.async('text');

    // Predefined color stays a named highlight …
    expect(docXml).toContain('<w:highlight w:val="yellow"');
    expect(docXml).toContain('<w:highlight w:val="green"');
    // … custom color stays run shading with the resolved fill …
    expect(docXml).toContain('w:fill="FFEB3B"');
    expect(docXml).toContain('<w:shd w:val="clear"');
    // … and the invalid shape Word silently drops is never emitted.
    expect(docXml).not.toMatch(/<w:highlight[^>]*w:fill=/);

    const tempPath = path.join(__dirname, '..', 'fixtures', '_temp-highlight-roundtrip.docx');
    fs.writeFileSync(tempPath, fs.readFileSync(downloadPath));
    try {
      await editor.loadDocxFile(tempPath);
      await assertions.assertDocumentContainsText(page, 'Named highlight yellow');
      await assertions.assertDocumentContainsText(page, 'Custom highlight pale yellow');
    } finally {
      if (fs.existsSync(tempPath)) fs.unlinkSync(tempPath);
    }
  });
});

test.describe('Theme color round-trip', () => {
  let editor: EditorPage;

  test.beforeEach(async ({ page }) => {
    editor = new EditorPage(page);
    await editor.goto();
    await editor.waitForReady();
  });

  test('themeColor/tint/shade survive save → reload, incl. table headers', async ({ page }) => {
    await editor.loadDocxFile(THEME_DOCX);

    await assertions.assertDocumentContainsText(page, 'Theme dark1 text.');
    await assertions.assertDocumentContainsText(page, 'Theme accent1 lighter 40%.');
    await assertions.assertDocumentContainsText(page, 'Header A');

    const downloadPath = await saveDownload(page);
    const zip = await JSZip.loadAsync(fs.readFileSync(downloadPath));
    const docXml = await zip.file('word/document.xml')!.async('text');

    // Theme attributes are written back alongside the resolved w:val.
    expect(docXml).toContain('w:val="000000"');
    expect(docXml).toContain('w:themeColor="dark1"');
    expect(docXml).toContain('w:themeColor="accent1"');
    expect(docXml).toContain('w:themeTint="66"');
    expect(docXml).toContain('w:themeShade="BF"');
    // Table header: themed text on a themed cell fill, resolved values kept.
    expect(docXml).toContain('w:themeColor="background1"');
    expect(docXml).toContain('w:themeFill="accent1"');
    expect(docXml).toContain('w:fill="4472C4"');
    expect(docXml).toContain('Header A');

    const tempPath = path.join(__dirname, '..', 'fixtures', '_temp-theme-roundtrip.docx');
    fs.writeFileSync(tempPath, fs.readFileSync(downloadPath));
    try {
      await editor.loadDocxFile(tempPath);
      await assertions.assertDocumentContainsText(page, 'Theme dark1 text.');
      await assertions.assertDocumentContainsText(page, 'Header A');
    } finally {
      if (fs.existsSync(tempPath)) fs.unlinkSync(tempPath);
    }
  });
});
